INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50611, 'Psalms 109:28', 'Psalms', 109, 28, 'هغوی دې ووایي لعنت راباندې، خو برکت راکړه ته کله چې وکاندي حمله نو دوی دې وشرمیږي خو وي دې خوشحاله خدمتګار دا ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_28.mp3', '', 1761754199, 1761754199),
(50612, 'Psalms 109:29', 'Psalms', 109, 29, 'زما مدعیان دې په شرمونو پټ شي هغوی دې پټ شي په لباس د شرم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_29.mp3', '', 1761754199, 1761754199),
(50613, 'Psalms 109:30', 'Psalms', 109, 30, 'په لوړ اواز به د څښتن نه زه مننه کوم د ټولو خلکو په حضور کې به ثنا د هغه وایمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_30.mp3', '', 1761754199, 1761754199),
(50614, 'Psalms 109:31', 'Psalms', 109, 31, 'ځکه ودریږي هغه د حاجتمندو تر‌څنګ او د هغو خلکو نه یې ساتي چې محکوموي هغوی په مرګ باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms109_verse_31.mp3', '', 1761754199, 1761754199),
(50615, 'Psalms 23:1', 'Psalms', 23, 1, 'دی څښتن زما شپونکی زه هېڅ شي ته محتاج نه یم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms23_verse_1.mp3', '', 1761754199, 1761754199),
(50616, 'Psalms 23:2', 'Psalms', 23, 2, 'راکوي ارام سرسبزه څړځایو کې هم مې بوځي اوبو ارامو لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms23_verse_2.mp3', '', 1761754199, 1761754199),
(50617, 'Psalms 23:3', 'Psalms', 23, 3, 'هغه ماته راکوي تازه قوت ما په سمه لاره بیایي د خپل نېک نامه دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms23_verse_3.mp3', '', 1761754199, 1761754199),
(50618, 'Psalms 23:4', 'Psalms', 23, 4, 'که د مرګ تیاره دره کې هم روان یم له خطره به زه ونه کړمه وېره ځکه ته راسره مل یې ای څښتنه ستا کوتک او امسا دواړه به زما په تسلۍ کاندي ساتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms23_verse_4.mp3', '', 1761754199, 1761754199),
(50619, 'Psalms 23:5', 'Psalms', 23, 5, 'ته زما د دښمنانو په حضور کې ته ماته غوړوې خپل دسترخوان هرکلی زما کوې ته د درانه مېلمه په شان ډکوې ته تر خولې پورې زما جام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms23_verse_5.mp3', '', 1761754199, 1761754199),
(50620, 'Psalms 23:6', 'Psalms', 23, 6, 'زه ډاډه یم چې ستا مینه او نېکي به تر عمره راسره وي ای څښتنه، ستا په کور کې به اوسېږم تل ترتله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms23_verse_6.mp3', '', 1761754199, 1761754199),
(50621, 'Psalms 14:1', 'Psalms', 14, 1, 'کم‌عقلان خپلو ځانونو سره وایي چې خدای نشته هغوی ټول دي فاسد شوي او کوي ډېر بد کارونه دوی کې هېڅ یو نېک کار نه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_1.mp3', '', 1761754199, 1761754199),
(50622, 'Psalms 14:2', 'Psalms', 14, 2, 'له اسمانه څښتن ساتي خپل نظر په انسانانو ترڅو وګوري کوم شته داسې عاقل چې رجوع وکړي خپل خدای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_2.mp3', '', 1761754199, 1761754199),
(50623, 'Psalms 14:3', 'Psalms', 14, 3, 'خو هغوی ټول ګمراهان شول ورسره هم فاسدان شول دوی کې هېڅ یو نېک کار نه کړي یو هم نه کړي نېک کردار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_3.mp3', '', 1761754199, 1761754199),
(50624, 'Psalms 14:4', 'Psalms', 14, 4, 'څښتن کړي دغه پوښتنه: «ایا دوی هېڅ نه پوهیږي؟ بدکاران ټول جاهلان دي؟ زما خلک داسې خوري دوی لکه وږي چې ډوډۍ خوري هېڅ دعا نه کوي ماته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_4.mp3', '', 1761754199, 1761754199),
(50625, 'Psalms 14:5', 'Psalms', 14, 5, 'خو په دوی به وېره راشي ځکه خدای مل دی د نېکانو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_5.mp3', '', 1761754199, 1761754199),
(50626, 'Psalms 14:6', 'Psalms', 14, 6, 'بدکاران د عاجزانو پلانونه شنډوي خو څښتن یې ساتندوی دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_6.mp3', '', 1761754199, 1761754199),
(50627, 'Psalms 14:7', 'Psalms', 14, 7, 'کاشکې راشي نجات د اسراییلو له صهیونه برکت چې کله بیا ورکړې څښتنه خپل ولس ته بیا خوشحاله کورنۍ به د یعقوب شي اسراییل به په دې کار سره خوشحال شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms14_verse_7.mp3', '', 1761754199, 1761754199),
(50628, 'Jeremiah 41:1', 'Jeremiah', 41, 1, 'هم د هغه کال په اوومه مياشت، اِسمٰعيل د نتنياه زوئ او د اليسمع نمسے چې د شاهى خاندان يو کس وو، او د اوچتې عُهدې آفسر وو، هغه د لسو سړو سره مصفاه ته د جدلياه سره مِلاوېدو له لاړو. کله چې هغوئ په شريکه روټۍ خوړله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_1.mp3', '', 1761754199, 1761754199),
(50629, 'Jeremiah 41:2', 'Jeremiah', 41, 2, 'نو ناګهانه د نتنياه زوئ اِسمٰعيل او د هغۀ لسو کسانو ټوپ کړو او خپلې تُورې يې راوويستلې او جدلياه يې قتل کړو، څوک چې د بابل بادشاه په يهوداه کښې ګورنر مقرر کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_2.mp3', '', 1761754199, 1761754199),
(50630, 'Jeremiah 41:3', 'Jeremiah', 41, 3, 'اِسمٰعيل هم هغه ټول يهوديان ووژل څوک چې په مصفاه کښې د جدلياه سره وُو، او هغه بابليان فوجيان هم چې هلته وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_3.mp3', '', 1761754199, 1761754199),
(50631, 'Jeremiah 41:4', 'Jeremiah', 41, 4, 'د جدلياه د قتلېدو نه يوه ورځ وروستو چې لا څوک هم د هغۀ په مرګ باندې خبر نۀ وُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_4.mp3', '', 1761754199, 1761754199),
(50632, 'Jeremiah 41:5', 'Jeremiah', 41, 5, 'اتيا کسان د شِکم، سيلا او سامريه نه د خُدائ کور ته راغلل چې عبادت وکړى. هغوئ خپلې ږيرې د غم په وجه خرئيلې وې، او د غم په وجه يې خپلې جامې هم شلولې وې او خپل ځانونه يې هم زخمى کړى وُو. او خپل ځان سره يې غله دانه او خوشبو مالِک خُدائ ته د نذرانې پېش کولو په توګه راوړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_5.mp3', '', 1761754199, 1761754199),
(50633, 'Jeremiah 41:6', 'Jeremiah', 41, 6, 'نو اِسمٰعيل د اوښکو نه په ډکو سترګو سره د مصفاه نه بهر ووتو او د هغه کسانو سره د ملاقات دپاره لاړو. کله چې هغه هغوئ ته ورسېدلو نو ورته يې ووئيل چې، ”راشئ، وګورئ چې د جدلياه د اخيقام زوئ سره څۀ شوى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_6.mp3', '', 1761754199, 1761754199),
(50634, 'Jeremiah 41:7', 'Jeremiah', 41, 7, 'خو چې څنګه هغوئ ښار ته ورننوتل، نو فوراً اِسمٰعيل او د هغۀ ملګرو ټول ووژل او د هغوئ لاشونه يې په يوه ډيګۍ کښې وروغورزول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_7.mp3', '', 1761754199, 1761754199),
(50635, 'Jeremiah 41:8', 'Jeremiah', 41, 8, 'خو په هغه ډله کښې لس کسان وُو چې هغوئ اِسمٰعيل سره دا خبره وکړه او ورته يې ووئيل چې، ”کۀ چرې تۀ مونږ ونۀ وژنې نو کوم غنم، اوربشې، او د زيتون تېل او شات چې مونږ پټ ذخيره کړى دى هغه به تا له راوړُو.“ نو په دې خبره هغۀ هغوئ ژوندى پرېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_8.mp3', '', 1761754199, 1761754199),
(50636, 'Jeremiah 41:9', 'Jeremiah', 41, 9, 'هغه د اوبو ډيګۍ چې اِسمٰعيل په کښې د هغه مړو لاشونه ورګزار کړل کوم چې هغۀ وژلى وُو هم هغه لويه ډيګۍ وه چې آسا بادشاه جوړه کړې وه چې کله هغۀ د مصفاه دفاع مضبوطه کړه چې خپل ځان د اِسرائيلو د بعشا بادشاه نه وساتى. اِسمٰعيل د نتنياه زوئ هغه د مړو نه ډکه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_9.mp3', '', 1761754199, 1761754199),
(50637, 'Jeremiah 41:10', 'Jeremiah', 41, 10, 'بيا اِسمٰعيل د بادشاه لوڼه او هغه ټول کسان چې نبوزردان د فوج مشر په مصفاه کښې جدلياه ته پرېښى وُو هغوئ ټول يې ګېر کړل او ځان سره يې د عمون د علاقې په طرف روان کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_10.mp3', '', 1761754199, 1761754199),
(50638, 'Jeremiah 41:11', 'Jeremiah', 41, 11, 'خو کله چې يوحانان د قريح زوئ او نور د فوج مشران د اِسمٰعيل د جرم نه خبر شول،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_11.mp3', '', 1761754199, 1761754199),
(50639, 'Jeremiah 41:12', 'Jeremiah', 41, 12, 'نو هغوئ خپل ټول سپاهيان راټول کړل او هغۀ پسې راووتل او په جبعون کښې د لوئ تالاب سره نزدې هغوئ هغه پېدا کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_12.mp3', '', 1761754199, 1761754199),
(50640, 'Jeremiah 41:13', 'Jeremiah', 41, 13, 'کله چې د اِسمٰعيل سره قېديانو يوحانان او ورسره نور فوجى مشران وليدل نو هغوئ ډېر خوشحاله شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_13.mp3', '', 1761754199, 1761754199),
(50641, 'Jeremiah 41:14', 'Jeremiah', 41, 14, 'او د مصفاه نه ټول قېديان وتښتېدل او د يوحانان مدد يې شروع کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_14.mp3', '', 1761754199, 1761754199),
(50642, 'Jeremiah 41:15', 'Jeremiah', 41, 15, 'خو اِسمٰعيل سره د خپلو هغه اتو کسانو دوستانو د عمون مُلک ته وتښتېدلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_15.mp3', '', 1761754199, 1761754199),
(50643, 'Jeremiah 41:16', 'Jeremiah', 41, 16, 'نو بيا يوحانان د قريح زوئ او نورو فوجى مشرانو، هغه ټول کسان د ځان سره روان کړل کوم چې هغوئ په جبعون کښې د اِسمٰعيل نه خلاص کړى وُو چې په هغوئ کښې سپاهيان، زنانه، ماشومان او د دربار خصيان شامل وُو، څوک چې د جدلياه د قتلولو نه وروستو اِسمٰعيل ګرفتار کړى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_16.mp3', '', 1761754199, 1761754199),
(50644, 'Jeremiah 41:17', 'Jeremiah', 41, 17, 'هغوئ مِصر ته د تللو وخت کښې د کِمهام سرائى چې بيت‌لحم سره نزدې وو هلته ايسار شُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_17.mp3', '', 1761754199, 1761754199),
(50645, 'Jeremiah 41:18', 'Jeremiah', 41, 18, 'نو د دې يرې نه چې کۀ بابليان په دې موضوع خبر شى چې اِسمٰعيل جدلياه قتل کړے دے، هغه څوک چې د بابل بادشاه د يهوداه ګورنر مقررولو، نو هغوئ به بيا څۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah41_verse_18.mp3', '', 1761754199, 1761754199),
(50646, 'Proverbs 20:1', 'Proverbs', 20, 1, 'شراب څښل انسان مسخره کوي او نشه شور او شخړې پیدا کوي نو هرڅوک چې په دې اخته شي د حکمت خاوند به نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_1.mp3', '', 1761754199, 1761754199),
(50647, 'Proverbs 20:2', 'Proverbs', 20, 2, 'د پاچا غوسه د غړمبېدونکي زمري په څېر وېره پیدا کوي څوک چې هغه راپاروي نو خپل ځان تباه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_2.mp3', '', 1761754199, 1761754199),
(50648, 'Proverbs 20:3', 'Proverbs', 20, 3, 'د جنګ نه ځان ویستل انسان ته عزت ورکوي خو هر جاهل سړی زر جګړې جوړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_3.mp3', '', 1761754199, 1761754199),
(50649, 'Proverbs 20:4', 'Proverbs', 20, 4, 'لټ انسان د کښت په موسم کې قلبه نه کوي او د لو په وخت کې چې هر شی لټوي هېڅ نه مومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_4.mp3', '', 1761754199, 1761754199),
(50650, 'Proverbs 20:5', 'Proverbs', 20, 5, 'د انسان د زړه خیالونه د ژورې څاه د اوبو په شان دي خو د پوهې خاوند هغه ترې بهر راوباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_5.mp3', '', 1761754199, 1761754199),
(50651, 'Proverbs 20:6', 'Proverbs', 20, 6, 'ډېر خلک د وفادارۍ دعوه کوي خو هېڅوک یو وفادار انسان پیدا کولای نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_6.mp3', '', 1761754199, 1761754199),
(50652, 'Proverbs 20:7', 'Proverbs', 20, 7, 'نېک انسان خپل ژوند په صداقت تېروي او راتلونکی نسل به یې تل بختور وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_7.mp3', '', 1761754199, 1761754199),
(50653, 'Proverbs 20:8', 'Proverbs', 20, 8, 'کله چې یو پاچا د قضاوت په تخت کښېني نو څه چې یې په نظر بد وي د بوسو په څېر یې بادوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_8.mp3', '', 1761754199, 1761754199),
(50654, 'Proverbs 20:9', 'Proverbs', 20, 9, 'څوک ویلی شي چې زما زړه پاک دی او زه پاک او بې‌ګناه یم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_9.mp3', '', 1761754199, 1761754199),
(50655, 'Proverbs 20:10', 'Proverbs', 20, 10, 'په ټګۍ سره اندازه کول او په غلطو کاڼو وزن کول دواړه د څښتن د کرکې سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_10.mp3', '', 1761754199, 1761754199),
(50656, 'Proverbs 20:11', 'Proverbs', 20, 11, 'حتی یو ماشوم هم په خپل چلند سره ځان داسې ښایي چې ګوندې کارونه یې پاک او رښتیني دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_11.mp3', '', 1761754199, 1761754199),
(50657, 'Proverbs 20:12', 'Proverbs', 20, 12, 'غوږونه چې اوري او سترګې چې ګوري دواړه څښتن جوړ کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_12.mp3', '', 1761754199, 1761754199),
(50658, 'Proverbs 20:13', 'Proverbs', 20, 13, 'که د خوب سره مینه کوې خوار به شې نو تل ویښ اوسه چې په ګېډه موړ شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_13.mp3', '', 1761754199, 1761754199),
(50659, 'Proverbs 20:14', 'Proverbs', 20, 14, 'اخیستونکی تل دا شکایت کوي چې «دا ښه نه دی! دا ښه نه دی!» خو کله یې چې واخلي نو بیا وایي: «ښه سودا مې وکړه!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_14.mp3', '', 1761754199, 1761754199),
(50660, 'Proverbs 20:15', 'Proverbs', 20, 15, 'سره زر او قیمتي غمي ډېر زیات پیدا کیږي خو هغه شونډې چې د علم خبرې کوي نه موندونکې ګاڼه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_15.mp3', '', 1761754199, 1761754199),
(50661, 'Proverbs 20:16', 'Proverbs', 20, 16, 'که څوک د یو پردي سړي ضمانت کوي نو کالي دې ترې ګرو واخلي او بیا دې د پردیو په ضمانت کې د ځان سره امانت وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_16.mp3', '', 1761754199, 1761754199),
(50662, 'Proverbs 20:17', 'Proverbs', 20, 17, 'حرامه ډوډۍ خوږه وي خو وروسته یې خوله د خاورو ډکیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_17.mp3', '', 1761754199, 1761754199),
(50663, 'Proverbs 20:18', 'Proverbs', 20, 18, 'خپلې نقشې تل په مشوره جوړوه او له ښې مشورې پرته جنګ ته مه ځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_18.mp3', '', 1761754199, 1761754199),
(50664, 'Proverbs 20:19', 'Proverbs', 20, 19, 'غیبت کوونکی د نورو راز ښکاره کوي نو له بېځایه خبرلوڅ انسان نه ځان لېرې ساته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_19.mp3', '', 1761754199, 1761754199),
(50665, 'Proverbs 20:20', 'Proverbs', 20, 20, 'څوک چې په خپل مور او پلار لعنت وایي نو د ژوند ډېوه به یې په توره تیاره کې مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_20.mp3', '', 1761754199, 1761754199),
(50666, 'Proverbs 20:21', 'Proverbs', 20, 21, 'کوم میراث چې زر تر‌لاسه کیږي نو په اخر کې به د برکت وسیله نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_21.mp3', '', 1761754199, 1761754199),
(50667, 'Proverbs 20:22', 'Proverbs', 20, 22, 'داسې مه وایه چې زه به د دې بدیو بدل اخلم. څښتن ته صبر وکړه چې ستا بدل واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_22.mp3', '', 1761754199, 1761754199),
(50668, 'Proverbs 20:23', 'Proverbs', 20, 23, 'څښتن په غلطو کاڼو وزن کولو نه کرکه کوي نو د تلې غلط کارول بد کار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_23.mp3', '', 1761754199, 1761754199),
(50669, 'Proverbs 20:24', 'Proverbs', 20, 24, 'د انسان د ژوند لاره څښتن ټاکلې ده نو بیا څنګه څوک خپله لار پېژندلی شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_24.mp3', '', 1761754199, 1761754199),
(50670, 'Proverbs 20:25', 'Proverbs', 20, 25, 'څوک چې په بیړه نذر مني او بیا فکر کوي نو خپل ځان په دام کې نښلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_25.mp3', '', 1761754199, 1761754199),
(50671, 'Proverbs 20:26', 'Proverbs', 20, 26, 'هوښیار پاچا بدکاران د غنمو په شان غوبل کوي او له ښو خلکو نه یې بېلوي لکه باد چې بوس بادوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_26.mp3', '', 1761754199, 1761754199),
(50672, 'Proverbs 20:27', 'Proverbs', 20, 27, 'د څښتن څراغ د انسان د روح لټون کوي چې د هغه د زړه ټول رازونه ښکاره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_27.mp3', '', 1761754199, 1761754199),
(50673, 'Proverbs 20:28', 'Proverbs', 20, 28, 'مینه او وفا د یو پاچا کلکه ساتنه کوي چې د مهربانۍ له امله به یې تخت تل ټینګ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_28.mp3', '', 1761754199, 1761754199),
(50674, 'Proverbs 20:29', 'Proverbs', 20, 29, 'د ځوانانو عزت د هغوی قوت او قدرت دی او سپین ویښته د مشرانو شان او شوکت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_29.mp3', '', 1761754199, 1761754199),
(50675, 'Proverbs 20:30', 'Proverbs', 20, 30, 'د ادب لښته شرارت لېرې کوي او د اصلاح زخمونه د انسان زړه دننه پاکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs20_verse_30.mp3', '', 1761754199, 1761754199),
(50676, 'Proverbs 17:1', 'Proverbs', 17, 1, 'په سکون سره د سپورې ډوډۍ خوړل ښه دي د هغه کور نه چې په کې کبابونه د جنګونو سره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_1.mp3', '', 1761754199, 1761754199),
(50677, 'Proverbs 17:2', 'Proverbs', 17, 2, 'هوښیار نوکر به د پلار په شرمېدلي زوی باندې حکم وکړي او د کورنۍ د نورو غړو په شان به په میراث کې برخه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_2.mp3', '', 1761754199, 1761754199),
(50678, 'Proverbs 17:3', 'Proverbs', 17, 3, 'سره او سپین زر په اور ازمایل کیږي خو د انسان د زړه امتحان څښتن اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_3.mp3', '', 1761754199, 1761754199),
(50679, 'Proverbs 17:4', 'Proverbs', 17, 4, 'بدکاره انسان د شرارت خبرو ته غوږ نیسي او دروغجن انسان د تباهۍ خبرې اوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_4.mp3', '', 1761754199, 1761754199),
(50680, 'Proverbs 17:5', 'Proverbs', 17, 5, 'څوک چې په خوارانو ملنډې وهي نو د هغوی د خالق سپکاوی کوي او څوک چې د بل په مصیبت خوشحالیږي نو بې‌سزا به پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_5.mp3', '', 1761754199, 1761754199),
(50681, 'Proverbs 17:6', 'Proverbs', 17, 6, 'لمسیان د خپلو مشرانو د سر تاج وي او ماشومان په خپل مور او پلار فخر کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_6.mp3', '', 1761754199, 1761754199),
(50682, 'Proverbs 17:7', 'Proverbs', 17, 7, 'که د بې‌عقله سړي دپاره لویې خبرې ښه کار نه وي نو د یو مشر سړي دپاره به دروغجنه ژبه څومره نامناسبه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_7.mp3', '', 1761754199, 1761754199),
(50683, 'Proverbs 17:8', 'Proverbs', 17, 8, 'رشوت د ورکوونکي په نظر د جادو په څېر دی هغه چې هر کار کوي نو بریالی کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_8.mp3', '', 1761754199, 1761754199),
(50684, 'Proverbs 17:9', 'Proverbs', 17, 9, 'د مینې غوښتونکی د نورو په ګناه پرده اچوي او د یوې خبرې تکراروونکی نژدې دوستان بېلوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_9.mp3', '', 1761754199, 1761754199),
(50685, 'Proverbs 17:10', 'Proverbs', 17, 10, 'په عقلمن انسان یوځل سزا ډېر تاثیر کوي خو کم‌عقل که سل لښتې ووهل شي بیاهم اصلاح به نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_10.mp3', '', 1761754199, 1761754199),
(50686, 'Proverbs 17:11', 'Proverbs', 17, 11, 'بدکاره انسان یوازې د سرکښۍ په لټه کې وي خو سخته سزا به ورته ورکړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_11.mp3', '', 1761754199, 1761754199),
(50687, 'Proverbs 17:12', 'Proverbs', 17, 12, 'د یوې اېږې سره چې بچي یې چا پټ کړي وي مخامخ کېدل ښه دي نه د یو کم‌عقل سره چې په خپل جهالت ټینګ ولاړ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_12.mp3', '', 1761754199, 1761754199),
(50688, 'Proverbs 17:13', 'Proverbs', 17, 13, 'که څوک د نېکۍ په بدل کې بدي کوي نو د کور نه به یې هېڅکله بدي لېرې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_13.mp3', '', 1761754199, 1761754199),
(50689, 'Proverbs 17:14', 'Proverbs', 17, 14, 'د دعوې شروع د اوبو د بند د سوري په شان ده نو د شخړو د شروع نه مخکې بحث بند کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_14.mp3', '', 1761754199, 1761754199),
(50690, 'Proverbs 17:15', 'Proverbs', 17, 15, 'مجرم پرېښودل او د بې‌ګناه محکومول د دواړو نه څښتن کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_15.mp3', '', 1761754199, 1761754199),
(50691, 'Proverbs 17:16', 'Proverbs', 17, 16, 'کم‌عقل انسان حکمت په پیسو نه شي اخیستلی ځکه چې هغه د پوهې د تر‌لاسه کولو دپاره هېڅ نیت نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_16.mp3', '', 1761754199, 1761754199),
(50692, 'Proverbs 17:17', 'Proverbs', 17, 17, 'یو ملګری هر وخت مینه کوي او ورور د سختې ورځې دپاره پیدا شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_17.mp3', '', 1761754199, 1761754199),
(50693, 'Proverbs 17:18', 'Proverbs', 17, 18, 'بې‌عقله سړی د بل چا په قرض کې لاس ورکوي او ناپوهه انسان د بل چا ضمانت په غاړه اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_18.mp3', '', 1761754199, 1761754199),
