(50698, 'Proverbs 17:23', 'Proverbs', 17, 23, 'بدکاره انسان په پټه رشوت اخلي او انصاف تر‌پښو لاندې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_23.mp3', '', 1761754199, 1761754199),
(50699, 'Proverbs 17:24', 'Proverbs', 17, 24, 'د عقل خاوند حکمت ته تل سترګې په لار وي خو د کم‌عقل نظر د ځمکې هرې خواته وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs17_verse_24.mp3', '', 1761754199, 1761754199),
